select

from ins_tag_client
where
1=1

    and tag_attribute = #{tagLibClientModel.tagAttribute}



    and tag_parent_id in

        #{item}




    and tag_type in

        #{item}



    and tag_type = #{tagLibClientModel.tagType}


    and id in

        #{item}



    and
    json_contains(energy_type,#{tagLibClientModel.energy,typeHandler=com.baomidou.mybatisplus.extension.handlers.JacksonTypeHandler})


    and tag_status = #{tagLibClientModel.tagStatus}


    and tag_status in

        #{item}



    and tag_name like concat('%',#{tagLibClientModel.tagName},'%')


    or tag_parent_id = '-1'



    order by tag_type,${tagLibClientModel.order}


    order by create_time asc

with recursive max_level_cte as ( select tag_type, max(`level`) as max_level from ins_tag_client where tag_attribute = 'Category'
and tag_type = #{tagLibClientModel.tagType}
and tag_type in
#{item}
group by tag_type ), matched_cte as ( select id, tag_parent_id from ins_tag_client where tag_attribute = 'Category'
and tag_type = #{tagLibClientModel.tagType}
and tag_type in
#{item}
and tag_name like concat('%', #{tagLibClientModel.tagName}, '%')
and 1 = 0
), ancestor_cte as ( select id, tag_parent_id from matched_cte union all select p.id, p.tag_parent_id from ins_tag_client p inner join ancestor_cte a on p.id = a.tag_parent_id where p.tag_attribute = 'Category' ), leaf_path_cte as ( select c.tag_type, c.id as leaf_id, c.id as node_id, c.tag_parent_id from ins_tag_client c inner join max_level_cte m on c.tag_type = m.tag_type and c.`level` = m.max_level where c.tag_attribute = 'Category' union all select p.tag_type, lp.leaf_id, p.id as node_id, p.tag_parent_id from ins_tag_client p inner join leaf_path_cte lp on p.id = lp.tag_parent_id where p.tag_attribute = 'Category' ), leaf_count_cte as ( select tag_type, node_id, count(distinct leaf_id) as leaf_count from leaf_path_cte group by tag_type, node_id ) select
from ins_tag_client t inner join max_level_cte m on t.tag_type = m.tag_type left join leaf_count_cte lc on t.tag_type = lc.tag_type and t.id = lc.node_id where t.tag_attribute = 'Category'
and t.id in ( select distinct id from ancestor_cte ) and ( t.`level` < m.max_level or t.id in ( select id from matched_cte ) )
and t.`level` < m.max_level
order by t.tag_type asc, t.`level` asc, t.create_time asc

with recursive category_cte as ( select id, tag_parent_id, tag_type from ins_tag_client where tag_attribute = 'Category'
and id = #{tagLibClientModel.tagParentId}
and tag_parent_id = '0' and tag_type = #{tagLibClientModel.tagType}
union all select t.id, t.tag_parent_id, t.tag_type from ins_tag_client t inner join category_cte c on t.tag_parent_id = c.id where t.tag_attribute = 'Category' ) select itc.id, itc.tag_parent_id, itc.tag_name, itc.tag_name_en, itc.tag_code, itc.tag_type, itc.tag_attribute, itc.identifier, itc.tag_status, itc.tag_description, itc.synonyms, itc.create_time, itc.update_time, if(su.firstname is null ,null,concat(su.firstname, '-', su.employee_id)) as update_user, itc.`level` from ins_tag_client itc left join voc_ms_be.sys_users su on su.id = itc.update_user where itc.identifier = 'FinalCategory'
and itc.tag_parent_id in ( select id from category_cte )
and itc.tag_type = #{tagLibClientModel.tagType}
and itc.tag_type = #{tagLibClientModel.tagType}
and itc.id in
#{item}
and itc.tag_code in
#{item}
and itc.tag_status = #{tagLibClientModel.tagStatus}
and itc.tag_status in
#{item}
and itc.tag_name like concat('%',#{tagLibClientModel.tagName},'%')
and itc.update_user = #{tagLibClientModel.operateUser}
order by ${tagLibClientModel.order}
order by itc.create_time asc

with recursive category_cte as ( select id, tag_parent_id, tag_type from ins_tag_client where tag_attribute = 'Category'
and id = #{tagLibClientModel.tagParentId}
and tag_parent_id = '0' and tag_type = #{tagLibClientModel.tagType}
union all select t.id, t.tag_parent_id, t.tag_type from ins_tag_client t inner join category_cte c on t.tag_parent_id = c.id where t.tag_attribute = 'Category' ) select count(1) from ins_tag_client where identifier = 'FinalCategory'
and tag_parent_id in ( select id from category_cte )
and tag_type = #{tagLibClientModel.tagType}
and tag_type = #{tagLibClientModel.tagType}
and id in
#{item}
and tag_code in
#{item}
and tag_status = #{tagLibClientModel.tagStatus}
and tag_status in
#{item}
and tag_name like concat('%',#{tagLibClientModel.tagName},'%')

